package com.cricketsim.logic

import java.util.Calendar

/**
 * The domestic level of a career: the state team's tournaments, the game's own domestic competitions of the player's country (India: the Syed Mushtaq Ali
 * Trophy, the Vijay Hazare Trophy and the Ranji Trophy; England: the Blast, the One-Day Cup and the County Championship; and so on). A season of them is
 * a list of [TournamentState]s made by the game's own tournament builders, with the player written into his state team's squad in the place of its weakest
 * player of his role. The player's state team is the first of the game's domestic teams of his state ([CareerProfile.domesticTeams]).
 */
object CareerDomestic {

    class Def(
        val tournamentId: String,
        val label: String,
        val shortLabel: String,
        val days: Int,
        val build: () -> Pair<List<Team>, Map<String, SquadTag>>,
        val make: (String, Pair<List<Team>, Map<String, SquadTag>>) -> TournamentState
    )

    /** The domestic tournaments of a country, shortest format first: the order they are played in a season. */
    fun defsFor(country: String): List<Def> = when (country) {
        "India" -> listOf(
            Def(DomesticWhiteBall.SMAT_ID, DomesticWhiteBall.SMAT_NAME, "T20", 1, { DomesticWhiteBall.buildTeams() }, { t, b -> DomesticWhiteBall.newTournament(DomesticWhiteBall.SMAT_ID, t, b) }),
            Def(DomesticWhiteBall.VHT_ID, DomesticWhiteBall.VHT_NAME, "50-over", 1, { DomesticWhiteBall.buildTeams() }, { t, b -> DomesticWhiteBall.newTournament(DomesticWhiteBall.VHT_ID, t, b) }),
            Def(Ranji.TOURNAMENT_ID, Ranji.TOURNAMENT_NAME, "Ranji", 4, { Ranji.buildTeams() }, { t, b -> Ranji.newTournament(t, b) })
        )
        "England" -> listOf(
            Def(CountyCricket.BLAST_ID, CountyCricket.BLAST_NAME, "T20", 1, { CountyCricket.buildTeams() }, { t, b -> CountyCricket.newTournament(CountyCricket.BLAST_ID, t, b) }),
            Def(CountyCricket.ODC_ID, CountyCricket.ODC_NAME, "50-over", 1, { CountyCricket.buildTeams() }, { t, b -> CountyCricket.newTournament(CountyCricket.ODC_ID, t, b) }),
            Def(CountyCricket.CC_ID, CountyCricket.CC_NAME, "Championship", 4, { CountyCricket.buildTeams() }, { t, b -> CountyCricket.newTournament(CountyCricket.CC_ID, t, b) })
        )
        "Australia" -> listOf(
            Def(AusDomestic.ODC_ID, AusDomestic.ODC_NAME, "50-over", 1, { AusDomestic.buildTeams() }, { t, b -> AusDomestic.newTournament(AusDomestic.ODC_ID, t, b) }),
            Def(AusDomestic.SHIELD_ID, AusDomestic.SHIELD_NAME, "Shield", 4, { AusDomestic.buildTeams() }, { t, b -> AusDomestic.newTournament(AusDomestic.SHIELD_ID, t, b) })
        )
        "South Africa" -> listOf(
            Def(SaDomestic.T20_ID, SaDomestic.T20_NAME, "T20", 1, { SaDomestic.buildTeams() }, { t, b -> SaDomestic.newTournament(SaDomestic.T20_ID, t, b) }),
            Def(SaDomestic.ODC_ID, SaDomestic.ODC_NAME, "50-over", 1, { SaDomestic.buildTeams() }, { t, b -> SaDomestic.newTournament(SaDomestic.ODC_ID, t, b) }),
            Def(SaDomestic.FOURDAY_ID, SaDomestic.FOURDAY_NAME, "4-day", 4, { SaDomestic.buildTeams() }, { t, b -> SaDomestic.newTournament(SaDomestic.FOURDAY_ID, t, b) })
        )
        "New Zealand" -> listOf(
            Def(NzDomestic.SMASH_ID, NzDomestic.SMASH_NAME, "T20", 1, { NzDomestic.buildTeams() }, { t, b -> NzDomestic.newTournament(NzDomestic.SMASH_ID, t, b) }),
            Def(NzDomestic.FORD_ID, NzDomestic.FORD_NAME, "50-over", 1, { NzDomestic.buildTeams() }, { t, b -> NzDomestic.newTournament(NzDomestic.FORD_ID, t, b) }),
            Def(NzDomestic.PLUNKET_ID, NzDomestic.PLUNKET_NAME, "Plunket", 4, { NzDomestic.buildTeams() }, { t, b -> NzDomestic.newTournament(NzDomestic.PLUNKET_ID, t, b) })
        )
        "Pakistan" -> listOf(
            Def(PakDomestic.GOLD_ID, PakDomestic.GOLD_NAME, "Gold", 4, { PakDomestic.buildTeams() }, { t, b -> PakDomestic.newTournament(PakDomestic.GOLD_ID, t, b) }),
            Def(PakDomestic.SILVER_ID, PakDomestic.SILVER_NAME, "Silver", 4, { PakDomestic.buildTeams() }, { t, b -> PakDomestic.newTournament(PakDomestic.SILVER_ID, t, b) })
        )
        else -> emptyList()
    }

    fun defFor(tournamentId: String): Def? =
        CareerWorld.COUNTRIES.flatMap { defsFor(it) }.find { it.tournamentId == tournamentId }

    /** The id the player has in every state tournament of his career. */
    fun playerId(careerId: String): String = "career_${careerId}_me"

    private fun v(p: Player): Double = maxOf(p.battingRating, p.bowlingRating) + p.fieldingRating * 0.1

    /** The player as the game's player, with his current ratings. */
    fun asPlayer(career: CareerProfile, teamId: String): Player = Player(
        id = playerId(career.id),
        teamId = teamId,
        name = career.fullName,
        role = CareerSeason.roleOf(career.role),
        battingRating = career.batting.coerceIn(1, 95),
        bowlingRating = career.bowling.coerceIn(1, 95),
        fieldingRating = career.fieldingRatingForState(),
        bowlingStyle = CareerSeason.styleOf(career.bowlingStyle)
    )

    private fun CareerProfile.fieldingRatingForState(): Int = fielding.coerceIn(1, 95)

    /** The squad with the player in the place of its weakest player of his role (a keeper is only replaced by a keeper). */
    private fun withPlayer(team: Team, me: Player): Team {
        val sameRole = team.players.filter { it.role == me.role }
        val candidates = if (me.role == PlayerRole.WICKETKEEPER && sameRole.isNotEmpty()) sameRole
        else sameRole.ifEmpty { team.players.filter { it.role != PlayerRole.WICKETKEEPER } }
        val victim = candidates.minByOrNull { v(it) } ?: return team
        return team.copy(players = team.players.map { if (it.id == victim.id) me else it })
    }

    /** The state team's squad as the game has it, without the player (used for the state selectors' decision). Null if the state has no team. */
    fun stateSquad(career: CareerProfile): Team? {
        val name = career.domesticTeams.firstOrNull() ?: return null
        for (def in defsFor(career.country)) {
            val built = def.build()
            val team = built.first.find { it.name == name }
            if (team != null) return team
        }
        return null
    }

    /** A season of the state team's tournaments (every one the team plays in), the player written into the squad, dated week by week after each other. */
    fun newSeason(career: CareerProfile): List<TournamentState>? {
        val name = career.domesticTeams.firstOrNull() ?: return null
        val pid = playerId(career.id)
        val start = CareerSeason.firstSaturday()
        var offsetWeeks = 0
        val out = ArrayList<TournamentState>()
        for (def in defsFor(career.country)) {
            val built = def.build()
            val team = built.first.find { it.name == name } ?: continue
            val state0 = try { def.make(team.id, built) } catch (e: Exception) { continue }
            if (state0.teams.none { it.id == team.id }) continue
            val me = asPlayer(career, team.id)
            val teams = state0.teams.map { t -> if (t.id == team.id) withPlayer(t, me) else t }
            val mine = state0.fixtures.count { it.homeId == team.id || it.awayId == team.id }
            val startAt = Calendar.getInstance().apply { timeInMillis = start.timeInMillis; add(Calendar.DAY_OF_YEAR, 7 * offsetWeeks) }.timeInMillis
            out.add(state0.copy(teams = teams, tags = state0.tags + (pid to SquadTag.DOMESTIC), createdAt = startAt))
            offsetWeeks += mine
        }
        return out.ifEmpty { null }
    }
}

package com.cricketsim.logic

import java.util.Locale

/**
 * The points tables of a career competition, as lines of text. A first-class tournament shows the points the game gives (a win, a draw, the bonus points);
 * the others show one table for each group or stage that is not a knockout (played, won, lost, no result, points, net run rate). The player's own club or
 * team is marked by the screen (each row carries the team id).
 */
object CareerTables {

    class Table(val title: String, val rows: List<Pair<String, String>>)

    private val NOT_A_TABLE = listOf(
        "final", "qualifier", "eliminator", "knockout", "challenger", "semi", "quarter", "bronze",
        "play-off", "playoff", "preliminary", "medal"
    )

    fun tables(state: TournamentState): List<Table> {
        val out = ArrayList<Table>()
        val multiDay = CareerSeason.competitionOf(state).days > 1
        val firstClass = if (CareerSeason.isClub(state)) emptyList() else state.fixtures.filter { it.result?.fcKind?.isNotEmpty() == true }
        if (firstClass.isNotEmpty()) {
            class Row(val id: String, val name: String) {
                var played = 0
                var won = 0
                var drawn = 0
                var points = 0
            }
            val rows = LinkedHashMap<String, Row>()
            for (f in firstClass) {
                val r = f.result ?: continue
                for ((id, pts) in listOf(f.homeId to r.homePoints, f.awayId to r.awayPoints)) {
                    if (id == null) continue
                    val teamName = state.teams.find { it.id == id }?.name ?: continue
                    val row = rows.getOrPut(id) { Row(id, teamName) }
                    row.played++
                    row.points += pts
                    if (r.winnerId == id) row.won++ else if (r.winnerId == null && r.fcKind == "DRAW") row.drawn++
                }
            }
            val sorted = rows.values.sortedWith(compareByDescending<Row> { it.points }.thenByDescending { it.won }.thenBy { it.name })
            out.add(Table("Points table", sorted.mapIndexed { i, row ->
                row.id to "${i + 1}. ${row.name}: played ${row.played}, won ${row.won}, drawn ${row.drawn}, points ${row.points}"
            }))
            return out
        }
        val stages = state.fixtures.map { it.stage }.distinct()
            .filter { stage -> NOT_A_TABLE.none { stage.lowercase(Locale.ROOT).contains(it) } }
        for (stage in stages) {
            val ids = state.fixtures.filter { it.stage == stage }.flatMap { listOfNotNull(it.homeId, it.awayId) }.toSet()
            val table = CplData.standings(state, stage).filter { it.team.id in ids && it.played > 0 }
            if (table.isEmpty()) continue
            out.add(Table(if (stages.size > 1) stage else "Points table", table.mapIndexed { i, r ->
                val nrr = String.format(Locale.US, "%+.3f", r.netRunRate)
                r.team.id to "${i + 1}. ${r.team.name}: played ${r.played}, won ${r.won}, lost ${r.lost}, " +
                    "${if (multiDay) "drawn" else "no result"} ${r.noResult}, points ${r.points}" + (if (multiDay) "" else ", net run rate $nrr")
            }))
        }
        return out
    }
}

package com.cricketsim.logic

import kotlin.math.roundToInt

/**
 * Who the selectors pick. The player is ranked against the club-mates of HIS OWN ROLE (batsmen against batsmen, bowlers against bowlers...)
 * by one number, his value in that role. An XI has a fixed number of places for each role ([ROLE_SLOTS]: one keeper, three batsmen, two batting
 * and two bowling all-rounders, three bowlers), and the career difficulty widens or narrows them: Very easy takes almost everyone, Medium the
 * places as they are, Hard and Legend fewer ([CareerWorld.selectionFactor]).
 *
 * Three things help a newcomer: his FIRST match is always a debut, his first three matches count one place in his favour, and a player of
 * 19 or younger gets one more place (the selectors back young talent). Recent form moves him up or down by as many as three places: the average
 * impact of his last three matches against 25 points, a place for every ten.
 */
object CareerSelection {

    /** Places in an XI for each role. */
    private val ROLE_SLOTS = mapOf(
        "Wicketkeeper-batsman" to 1,
        "Batsman" to 3,
        "Batting all-rounder" to 2,
        "Bowling all-rounder" to 2,
        "Bowler" to 3
    )

    class Decision(
        val selected: Boolean,
        val rank: Int,
        val cutoff: Int,
        val squadSize: Int,
        val formAdjust: Int,
        val reason: String
    )

    private fun value(p: CareerPlayer): Double = when (p.role) {
        "Batsman", "Wicketkeeper-batsman" -> p.batting * 0.8 + p.fielding * 0.2
        "Bowler" -> p.bowling * 0.8 + p.fielding * 0.2
        "Batting all-rounder" -> p.batting * 0.55 + p.bowling * 0.35 + p.fielding * 0.1
        else -> p.bowling * 0.55 + p.batting * 0.35 + p.fielding * 0.1
    }

    private fun ordinal(n: Int): String = when {
        n % 100 in 11..13 -> "${n}th"
        n % 10 == 1 -> "${n}st"
        n % 10 == 2 -> "${n}nd"
        n % 10 == 3 -> "${n}rd"
        else -> "${n}th"
    }

    private fun plural(role: String): String = if (role.endsWith("man")) role.dropLast(3) + "men" else role + "s"

    fun decide(career: CareerProfile): Decision {
        val squad = career.myClub?.players ?: return Decision(true, 1, 11, 15, 0, "")
        val me = squad.find { it.isUser } ?: return Decision(true, 1, 11, squad.size, 0, "")
        val group = squad.filter { it.role == me.role }.sortedByDescending { value(it) }
        val rank = group.indexOfFirst { it.isUser }.let { if (it < 0) group.size else it + 1 }
        val factor = CareerWorld.selectionFactor(career.difficulty)
        val slots = ROLE_SLOTS[me.role] ?: 3
        val cutoff = (slots / factor).roundToInt().coerceIn(1, group.size)
        val form = career.form.orEmpty().takeLast(3)
        val adjust = if (form.isEmpty()) 0 else ((form.average() - 25.0) / 10.0).roundToInt().coerceIn(-3, 3)
        val grace = (if (career.matchesPlayed < 3) 1 else 0) + (if (career.age <= 19) 1 else 0)
        val debut = career.matchesPlayed == 0
        val captain = career.isCaptain
        val selected = captain || debut || rank - adjust - grace <= cutoff

        val formNote = when {
            adjust > 0 -> " Your good form moves you up ${if (adjust == 1) "a place" else "$adjust places"}."
            adjust < 0 -> " Your poor form drops you ${if (adjust == -1) "a place" else "${-adjust} places"}."
            else -> ""
        }
        val graceNote = when {
            grace == 2 -> " The selectors are giving a young newcomer two extra places."
            grace == 1 -> if (career.age <= 19) " The selectors back young players: one extra place." else " You are still new, so you get one extra place."
            else -> ""
        }
        val base = "You rank ${ordinal(rank)} of ${group.size} ${plural(me.role.lowercase())} at your club, and the selectors on ${career.difficulty.lowercase()} pick the top $cutoff.$graceNote$formNote"
        val reason = when {
            captain -> "You are the captain, so you always play, and you make the team decisions. $base"
            debut -> "You are in the XI. The selectors give every new player a debut: this is your first match. $base"
            selected -> "You are in the XI. $base"
            else -> "You are not in the XI. $base Score runs, take wickets or improve your ratings to move up."
        }
        return Decision(selected, rank, cutoff, group.size, adjust, reason)
    }

    private fun v(p: Player): Double = maxOf(p.battingRating, p.bowlingRating) + p.fieldingRating * 0.1

    /**
     * The player's club squad as the selectors leave it for a match. Not selected: the squad without him. Selected: the club's best
     * eleven, with him in it (in the place of the weakest player of his own kind; the keeper keeps his place unless he is the keeper).
     */
    fun squadForMatch(squad: Team, tags: Map<String, SquadTag>, stadium: Stadium, userPlayerId: String, selected: Boolean): Team {
        val me = squad.players.find { it.id == userPlayerId } ?: return squad
        if (!selected) return squad.copy(players = squad.players.filter { it.id != userPlayerId })
        val best = CplSimulator.pickXI(squad, tags, stadium)
        if (best.players.any { it.id == userPlayerId }) return best
        val others = best.players.filter { it.role != PlayerRole.WICKETKEEPER || me.role == PlayerRole.WICKETKEEPER }
        val sameKind = others.filter { it.role == me.role }
        val victim = (if (sameKind.isEmpty()) others else sameKind).minByOrNull { v(it) } ?: return best
        return best.copy(players = best.players.map { if (it.id == victim.id) me else it })
    }

    /** The eleven the player's club takes the field with for a match he is selected for (captain and keeper set), the player at his batting number. */
    fun matchXI(squad: Team, tags: Map<String, SquadTag>, stadium: Stadium, userPlayerId: String, battingNumber: Int = 0): Team {
        val xi = CplSimulator.pickXI(squadForMatch(squad, tags, stadium, userPlayerId, true), tags, stadium)
        if (battingNumber !in 1..11) return xi
        val me = xi.players.find { it.id == userPlayerId } ?: return xi
        val order = xi.players.filter { it.id != userPlayerId }.toMutableList()
        order.add((battingNumber - 1).coerceIn(0, order.size), me)
        return xi.copy(players = order)
    }

    // ------------------------------------------------------------ the state level

    private fun pv(p: Player): Double = when (p.role) {
        PlayerRole.BATSMAN, PlayerRole.WICKETKEEPER -> p.battingRating * 0.8 + p.fieldingRating * 0.2
        PlayerRole.BOWLER -> p.bowlingRating * 0.8 + p.fieldingRating * 0.2
        else -> p.battingRating * 0.45 + p.bowlingRating * 0.45 + p.fieldingRating * 0.1
    }

    private fun roleSlots(role: PlayerRole): Int = if (role == PlayerRole.WICKETKEEPER) 1 else 3

    /** The decision for the player's next match in a competition: the club's rank among his club-mates, or the state squad's. */
    fun forState(career: CareerProfile, state: TournamentState): Decision =
        if (CareerSeason.isClub(state)) decide(career) else decideAtState(career, state)

    /**
     * Once called up, the player is ranked in the state squad among the players of his role (the squad is bigger and stronger than a club's):
     * the selectors take the top three of a role (one keeper), widened or narrowed by the difficulty. His first state match is a debut; his first
     * three state matches and being 19 or younger each count a place in his favour; form still moves him up or down by up to three places.
     */
    fun decideAtState(career: CareerProfile, state: TournamentState): Decision {
        val team = state.teams.find { it.id == state.userTeamId } ?: return Decision(true, 1, 11, 15, 0, "")
        val me = team.players.find { it.id == CareerSeason.playerIdIn(state, career) } ?: return Decision(true, 1, 11, team.players.size, 0, "")
        val group = team.players.filter { it.role == me.role }.sortedByDescending { pv(it) }
        val rank = group.indexOfFirst { it.id == me.id }.let { if (it < 0) group.size else it + 1 }
        val factor = CareerWorld.selectionFactor(career.difficulty)
        val cutoff = (roleSlots(me.role) / factor).roundToInt().coerceIn(1, group.size)
        val form = career.form.orEmpty().takeLast(3)
        val adjust = if (form.isEmpty()) 0 else ((form.average() - 25.0) / 10.0).roundToInt().coerceIn(-3, 3)
        val grace = (if (career.stateMatches < 3) 1 else 0) + (if (career.age <= 19) 1 else 0)
        val debut = career.stateMatches == 0
        val selected = debut || rank - adjust - grace <= cutoff
        val formNote = when {
            adjust > 0 -> " Your good form moves you up ${if (adjust == 1) "a place" else "$adjust places"}."
            adjust < 0 -> " Your poor form drops you ${if (adjust == -1) "a place" else "${-adjust} places"}."
            else -> ""
        }
        val base = "You rank ${ordinal(rank)} of ${group.size} players of your role in the ${team.name} squad, and the selectors on ${career.difficulty.lowercase()} pick the top $cutoff.$formNote"
        val reason = when {
            debut -> "You are in the XI. The state selectors give every new player a debut: this is your first state match. $base"
            selected -> "You are in the XI. $base"
            else -> "You are not in the XI. $base Score runs, take wickets or improve your ratings to move up."
        }
        return Decision(selected, rank, cutoff, group.size, adjust, reason)
    }

    /**
     * The decision at the end of a season: is the player called up to the state squad (or does he keep his place in it)? He is ranked, with his current
     * ratings, against the squad's players of his role. His form (the average impact of his last five matches against 25, a place for every ten) and being
     * 19 or younger help him; a player already in the squad gets two places of loyalty.
     */
    fun stateDecision(career: CareerProfile, squad: Team): Decision {
        val role = CareerSeason.roleOf(career.role)
        val myValue = when (role) {
            PlayerRole.BATSMAN, PlayerRole.WICKETKEEPER -> career.batting * 0.8 + career.fielding * 0.2
            PlayerRole.BOWLER -> career.bowling * 0.8 + career.fielding * 0.2
            else -> career.batting * 0.45 + career.bowling * 0.45 + career.fielding * 0.1
        }
        val group = squad.players.filter { it.role == role }
        val rank = 1 + group.count { pv(it) > myValue }
        val factor = CareerWorld.selectionFactor(career.difficulty)
        val cutoff = (roleSlots(role) / factor).roundToInt().coerceIn(1, group.size + 1)
        val form = career.form.orEmpty().takeLast(5)
        val adjust = if (form.isEmpty()) 0 else ((form.average() - 25.0) / 10.0).roundToInt().coerceIn(-3, 3)
        val grace = (if (career.age <= 19) 1 else 0) + (if (career.isState) 2 else 0)
        val selected = rank - adjust - grace <= cutoff
        val formNote = when {
            adjust > 0 -> " Your good form moves you up ${if (adjust == 1) "a place" else "$adjust places"}."
            adjust < 0 -> " Your poor form drops you ${if (adjust == -1) "a place" else "${-adjust} places"}."
            else -> ""
        }
        val loyal = if (career.isState) " As a player already in the squad you get two places of loyalty." else ""
        val youth = if (career.age <= 19) " The selectors back young players." else ""
        val base = "With your ratings you would rank ${ordinal(rank)} among the ${group.size} players of your role in the ${squad.name} squad, and the selectors on ${career.difficulty.lowercase()} pick the top $cutoff.$youth$loyal$formNote"
        val reason = if (selected) {
            if (career.isState) "The ${squad.name} selectors keep you in the squad. $base" else "The ${squad.name} selectors call you up to the state squad! $base"
        } else {
            if (career.isState) "The ${squad.name} selectors drop you from the squad. $base" else "The ${squad.name} selectors do not call you up this year. $base Keep scoring runs and taking wickets and improving."
        }
        return Decision(selected, rank, cutoff, group.size, adjust, reason)
    }
}

package com.cricketsim.logic

import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale
import kotlin.math.abs
import kotlin.random.Random

/**
 * The season a career plays in: THREE competitions between the district clubs of the player's state, each a league in which every club plays the
 * others once: a T20 League (20 overs a side), a 50-Over League and a 3-Day League (three-day matches, two innings each, played like a Test).
 * Each competition is a [TournamentState], the game's own tournament record (fixtures, results, scorecards, player statistics), with its own
 * table and statistics; its id is "career_<career id>_<t20|odi|3day>". The matches take turns week by week: a T20 match on a Saturday, a
 * 50-over match the next week, a three-day match (Friday to Sunday) the week after, and so on.
 */
object CareerSeason {

    class Competition(val key: String, val label: String, val shortLabel: String, val days: Int)

    val COMPETITIONS = listOf(
        Competition("t20", "T20 League", "T20", 1),
        Competition("odi", "50-Over League", "50-over", 1),
        Competition("3day", "3-Day League", "3-day", 3)
    )

    fun tournamentId(careerId: String, key: String): String = "career_${careerId}_$key"

    val CLUB_KEYS = COMPETITIONS.map { it.key }

    /** A club league ("career_<id>_t20" ...), as opposed to a state tournament of the domestic level. */
    fun isClub(state: TournamentState): Boolean = state.tournamentId.startsWith("career_")

    /** A competition's file key: "t20", "odi", "3day" for the club leagues, the tournament id for a state tournament. */
    fun keyOf(state: TournamentState): String = if (isClub(state)) state.tournamentId.substringAfterLast('_') else state.tournamentId

    /** The file a competition of a season is saved in (the first season's club leagues keep the names the first versions gave them). */
    fun seasonFile(careerId: String, season: Int, key: String): String =
        if (season <= 1 && key in CLUB_KEYS) "career_season_${careerId}_$key.json" else "career_season_${careerId}_s${maxOf(season, 1)}_$key.json"

    fun compIndex(state: TournamentState): Int = COMPETITIONS.indexOfFirst { it.key == keyOf(state) }.coerceAtLeast(0)

    fun competitionOf(state: TournamentState): Competition {
        if (isClub(state)) return COMPETITIONS[compIndex(state)]
        val def = CareerDomestic.defFor(state.tournamentId)
        return Competition(state.tournamentId, def?.label ?: state.name, def?.shortLabel ?: "Domestic", def?.days ?: 1)
    }

    /** The player's id in a competition: his club player's id in the club leagues, his one fixed id in a state tournament. */
    fun playerIdIn(state: TournamentState, career: CareerProfile): String? =
        if (isClub(state)) userPlayerId(career) else CareerDomestic.playerId(career.id)

    /** The rules a competition is played by (TournamentRules asks for them by tournament id). */
    fun rulesFor(tournamentId: String): MatchRules? = when (tournamentId.substringAfterLast('_')) {
        "t20" -> MatchRules(overs = 20, restrictionBalls = 36, fieldersOutside = 2, drsReviews = 0, rainEnabled = true, maxOversPerBowler = 4, noSuperOver = true)
        "odi" -> MatchRules(overs = 50, restrictionBalls = 60, fieldersOutside = 2, drsReviews = 0, rainEnabled = true, maxOversPerBowler = 10, noSuperOver = true)
        "3day" -> TestMatch.rulesForDays(3)
        else -> null
    }

    fun clubId(careerId: String, index: Int): String = "career_${careerId}_c$index"

    /** The team id of the player's own club in the season. */
    fun userClubId(career: CareerProfile): String? {
        val index = career.clubs.indexOfFirst { it.name == career.club }
        return if (index < 0) null else clubId(career.id, index)
    }

    internal fun roleOf(label: String): PlayerRole = when (label) {
        "Batsman" -> PlayerRole.BATSMAN
        "Wicketkeeper-batsman" -> PlayerRole.WICKETKEEPER
        "Bowler" -> PlayerRole.BOWLER
        else -> PlayerRole.ALL_ROUNDER
    }

    internal fun styleOf(label: String): BowlingStyle =
        if (label == "Off break" || label == "Leg break" || label == "Orthodox spin" || label == "Wrist spin") BowlingStyle.SPIN else BowlingStyle.PACE

    /** A club as the game's team: its made-up players become the game's players (ids "<club id>_p<number>"). */
    fun clubTeam(careerId: String, index: Int, club: CareerClub): Team {
        val teamId = clubId(careerId, index)
        val players = club.players.mapIndexed { i, p ->
            Player(
                id = "${teamId}_p$i",
                teamId = teamId,
                name = p.name,
                role = roleOf(p.role),
                battingRating = p.batting.coerceIn(1, 95),
                bowlingRating = p.bowling.coerceIn(1, 95),
                fieldingRating = p.fielding.coerceIn(1, 95),
                bowlingStyle = styleOf(p.bowlingStyle)
            )
        }
        fun avg(f: (Player) -> Int) = if (players.isEmpty()) 40 else players.sumOf(f) / players.size
        return Team(teamId, club.name, "", avg { it.battingRating }, avg { it.bowlingRating }, avg { it.fieldingRating }, players)
    }

    /** Every pair once, round by round (the circle method). */
    private fun roundRobin(ids: List<String>): List<Pair<String, String>> {
        val rot = ids.toMutableList()
        if (rot.size % 2 == 1) rot.add("")
        val n = rot.size
        val out = ArrayList<Pair<String, String>>()
        repeat(n - 1) { round ->
            for (i in 0 until n / 2) {
                val a = rot[i]
                val b = rot[n - 1 - i]
                if (a.isNotEmpty() && b.isNotEmpty()) out.add(if ((i + round) % 2 == 0) a to b else b to a)
            }
            rot.add(1, rot.removeAt(n - 1))
        }
        return out
    }

    /** The first Saturday at least a week away, at nine in the morning. */
    internal fun firstSaturday(): Calendar {
        val c = Calendar.getInstance()
        c.set(Calendar.HOUR_OF_DAY, 9); c.set(Calendar.MINUTE, 0); c.set(Calendar.SECOND, 0); c.set(Calendar.MILLISECOND, 0)
        var ahead = (Calendar.SATURDAY - c.get(Calendar.DAY_OF_WEEK) + 7) % 7
        if (ahead == 0) ahead = 7
        c.add(Calendar.DAY_OF_YEAR, ahead)
        return c
    }

    /** The three competitions of a career's season (T20, 50-over, 3-day), or null if its state has fewer than two clubs. */
    fun newSeason(career: CareerProfile): List<TournamentState>? {
        val clubs = career.clubs
        if (clubs.size < 2) return null
        val teams = clubs.mapIndexed { i, c -> clubTeam(career.id, i, c) }
        val tags = LinkedHashMap<String, SquadTag>()
        teams.forEach { t -> t.players.forEach { tags[it.id] = SquadTag.DOMESTIC } }
        val all = AllStadiums.list()
        val grounds = all.filter { it.country == career.country }.ifEmpty { all }
        val offset = abs(career.state.hashCode()) % grounds.size
        val groundOf = teams.indices.associate { teams[it].id to grounds[(offset + it * 3) % grounds.size].id }
        val start = firstSaturday()
        val year = start.get(Calendar.YEAR)
        return COMPETITIONS.map { comp ->
            val fixtures = ArrayList<TournamentFixture>()
            roundRobin(teams.map { it.id }).forEach { (home, away) ->
                fixtures.add(TournamentFixture(fixtures.size, fixtures.size + 1, CplData.LEAGUE, home, away, groundOf.getValue(home)))
            }
            TournamentState(
                version = CplData.SAVE_VERSION,
                tournamentId = tournamentId(career.id, comp.key),
                name = "${career.state} ${comp.label} $year",
                userTeamId = userClubId(career) ?: teams.first().id,
                teams = teams,
                tags = tags,
                fixtures = fixtures,
                createdAt = start.timeInMillis
            )
        }
    }

    /** The round of a competition a fixture is in: half the clubs (rounded down) play in a round, so each club plays once. */
    fun roundOf(state: TournamentState, fixture: TournamentFixture): Int = (fixture.number - 1) / maxOf(1, state.teams.size / 2)

    /** The weeks of the three competitions take turns: T20 in week 1, 50-over in week 2, 3-day in week 3, T20 in week 4... */
    fun weekOf(state: TournamentState, fixture: TournamentFixture): Int = roundOf(state, fixture) * COMPETITIONS.size + compIndex(state)

    /** The first day of the match: a Saturday, or the Friday before it for a three-day match. */
    fun dateMillis(state: TournamentState, fixture: TournamentFixture): Long {
        val c = Calendar.getInstance()
        c.timeInMillis = state.createdAt
        if (isClub(state)) {
            c.add(Calendar.DAY_OF_YEAR, 7 * weekOf(state, fixture) - (if (competitionOf(state).days > 1) 1 else 0))
        } else {
            // A state tournament: the player's matches, one a week, from the week the tournament starts.
            val mine = state.fixtures.filter { CplSimulator.involves(it, state.userTeamId) }
            val index = mine.indexOfFirst { it.id == fixture.id }.let { if (it < 0) fixture.number else it }
            c.add(Calendar.DAY_OF_YEAR, 7 * index)
        }
        return c.timeInMillis
    }

    fun dateText(millis: Long): String = SimpleDateFormat("EEEE d MMMM yyyy", Locale.getDefault()).format(Date(millis))

    /** "Saturday 6 December 2026", or "Friday 5 December 2026 to Sunday 7 December 2026" for a three-day match. */
    fun whenText(state: TournamentState, fixture: TournamentFixture): String {
        val start = dateMillis(state, fixture)
        val days = competitionOf(state).days
        if (days <= 1) return dateText(start)
        val end = Calendar.getInstance().apply { timeInMillis = start; add(Calendar.DAY_OF_YEAR, days - 1) }.timeInMillis
        return "${dateText(start)} to ${dateText(end)}"
    }

    /** No match that can be played is left (a knockout match whose teams are not known yet does not count: it comes when the table is settled). */
    fun isComplete(state: TournamentState): Boolean = state.fixtures.none { it.result == null && it.homeId != null && it.awayId != null }

    /** The champions once every match is played: the club top of the table, or the winner of a state tournament. */
    fun champion(state: TournamentState): Team? =
        if (!isComplete(state)) null
        else if (isClub(state)) CplData.standings(state).firstOrNull()?.team
        else CplSimulator.champion(state)

    fun nameOf(state: TournamentState, teamId: String?): String = state.teams.find { it.id == teamId }?.name ?: "?"

    /** The game-player id of the career's player in the season (null on a career without club teams). */
    fun userPlayerId(career: CareerProfile): String? {
        val clubIndex = career.clubs.indexOfFirst { it.name == career.club }
        if (clubIndex < 0) return null
        val i = career.clubs[clubIndex].players.indexOfFirst { it.isUser }
        return if (i < 0) null else "${clubId(career.id, clubIndex)}_p$i"
    }

    /** A competition's copy of the player gets his current ratings (they grow as he plays). */
    fun withUserPlayer(state: TournamentState, career: CareerProfile): TournamentState {
        val pid = playerIdIn(state, career) ?: return state
        return state.copy(teams = state.teams.map { t ->
            if (t.players.none { it.id == pid }) t
            else t.copy(players = t.players.map { p ->
                if (p.id == pid) p.copy(
                    battingRating = career.batting.coerceIn(1, 95),
                    bowlingRating = career.bowling.coerceIn(1, 95),
                    fieldingRating = career.fielding.coerceIn(1, 95)
                ) else p
            })
        })
    }

    /** Simulates the player's own fixture with the selectors' decision: he is in the club's XI or left out of it. Any competition's format. */
    fun simulateMine(state: TournamentState, fixture: TournamentFixture, career: CareerProfile, random: Random): TournamentState {
        val stadium = CplData.stadium(fixture.stadiumId) ?: return state
        val pid = playerIdIn(state, career) ?: return CplSimulator.simulateFixture(state, fixture, random)
        val selected = CareerSelection.forState(career, state).selected
        val mine = state.teams.find { it.id == state.userTeamId } ?: return state
        val adjusted = CareerSelection.squadForMatch(mine, state.tags, stadium, pid, selected)
        val after = CplSimulator.simulateFixture(state.copy(teams = state.teams.map { if (it.id == state.userTeamId) adjusted else it }), fixture, random)
        return after.copy(teams = state.teams)
    }

    /** The player's next unplayed match in any competition (the one that comes first in the calendar), with its competition's index. */
    fun nextMine(states: List<TournamentState>): Pair<Int, TournamentFixture>? {
        var best: Pair<Int, TournamentFixture>? = null
        var bestDate = Long.MAX_VALUE
        states.forEachIndexed { i, s ->
            val f = s.fixtures.firstOrNull { it.result == null && CplSimulator.involves(it, s.userTeamId) } ?: return@forEachIndexed
            val d = dateMillis(s, f)
            if (d < bestDate) {
                bestDate = d
                best = i to f
            }
        }
        return best
    }

    class Advance(val states: List<TournamentState>, val career: CareerProfile, val lines: List<String>)

    /**
     * Moves the season on, match by match in calendar order. The other clubs' matches before the player's next match (in its competition) are
     * always played. [includeMine] also simulates the player's match (with the selectors' decision, then his form and ratings); [whole] goes
     * on to the end of the season, all three competitions.
     */
    fun advance(states: List<TournamentState>, career: CareerProfile, random: Random, includeMine: Boolean, whole: Boolean): Advance {
        var list = states
        var c = career
        val lines = ArrayList<String>()
        var guard = 0
        while (guard < 300) {
            guard++
            var next = nextMine(list)
            if (next == null && whole) {
                // Nothing left for the player: finish the other matches, which may open a knockout match for his team.
                list = list.map { CplSimulator.run(it, SimMode.ALL, random) }
                next = nextMine(list)
            }
            if (next == null) break
            val ci = next.first
            val ran = CplSimulator.run(list[ci], SimMode.UNTIL_MINE, random)
            list = list.mapIndexed { i, x -> if (i == ci) ran else x }
            if (!includeMine && !whole) break
            val mine = ran.fixtures.firstOrNull { it.result == null && CplSimulator.involves(it, ran.userTeamId) } ?: break
            val pid = playerIdIn(ran, c)
            val before = if (pid != null) ran.playerStats[pid] else null
            val played = simulateMine(ran, mine, c, random)
            val result = CareerProgress.afterMatch(c, before, if (pid != null) played.playerStats[pid] else null, random)
            c = result.career
            val updated = withUserPlayer(played, c)
            list = list.mapIndexed { i, x -> if (i == ci) updated else x }
            lines.add(
                "${competitionOf(updated).label}: ${nameOf(updated, mine.homeId)} v ${nameOf(updated, mine.awayId)}. " +
                    "${updated.fixtures.find { it.id == mine.id }?.result?.summary ?: ""} ${result.text}"
            )
            if (!whole) break
        }
        if (whole) list = list.map { withUserPlayer(CplSimulator.run(it, SimMode.ALL, random), c) }
        return Advance(list, c, lines)
    }

    class NextSeason(val career: CareerProfile, val states: List<TournamentState>, val keys: List<String>, val text: String)

    /**
     * The next season. The player is a year older. The state selectors look at him (his ratings in the state squad, his form, the difficulty): called up, he plays
     * the state team's tournaments; kept, he plays them again; not called up (or dropped), he plays another club season.
     */
    fun nextSeason(career: CareerProfile): NextSeason {
        val older = career.copy(age = career.age + 1, season = maxOf(1, career.season) + 1)
        var text = "A new season begins. You are ${older.age}. "
        val squad = CareerDomestic.stateSquad(career)
        if (squad != null) {
            val decision = CareerSelection.stateDecision(career, squad)
            text += decision.reason + " "
            if (decision.selected) {
                val withLevel = older.copy(level = "State")
                val domestic = CareerDomestic.newSeason(withLevel)
                if (domestic != null) {
                    val keys = domestic.map { keyOf(it) }
                    return NextSeason(withLevel.copy(seasonKeys = keys), domestic, keys, text + "You play for the ${squad.name} squad this season.")
                }
            }
        }
        val club = older.copy(level = "District")
        val states = newSeason(club) ?: emptyList()
        val keys = states.map { keyOf(it) }
        text += if (career.isState) "You go back to district club cricket for ${career.club}." else "You stay with ${career.club} for another season of club cricket."
        return NextSeason(club.copy(seasonKeys = keys), states, keys, text)
    }
}

